(5886591, 856988, 65234, '<td valign="top">Very sweet expression; how can you resist?  Think I would prefer this in more muted tones or BW since the yellow in the wood is a little overwhelming.</td>', 'Very sweet expression; how can you resist?  Think I would prefer this in more muted tones or BW since the yellow in the wood is a little overwhelming.', '2010-03-02 08:43:08.000000', NULL, 1),
(5886596, 857501, 65234, '<td valign="top">Looks like brand new stairs have made it into a renovation project.  Narrow, certainly, but it looks like an interesting older house.  The off-kilter angle encouraged my eye to wander around the scene.</td>', 'Looks like brand new stairs have made it into a renovation project.  Narrow, certainly, but it looks like an interesting older house.  The off-kilter angle encouraged my eye to wander around the scene.', '2010-03-02 08:46:31.000000', NULL, 1),
(5886598, 856741, 65234, '<td valign="top">All too familiar scene around these parts in February!  Like this in B&amp;W.</td>', 'All too familiar scene around these parts in February!  Like this in B&W.', '2010-03-02 08:47:09.000000', NULL, 1),
(5886600, 857488, 65234, '<td valign="top">Pretty wispy clouds.</td>', 'Pretty wispy clouds.', '2010-03-02 08:47:57.000000', NULL, 1),
